function ce($v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
function csrf(): string { return '<input type="hidden" name="csrf_token" value="'.ce($_SESSION['content_csrf_token']).'">'; }
function verify_csrf(): void { if (!hash_equals($_SESSION['content_csrf_token'] ?? '', (string)($_POST['csrf_token'] ?? ''))) { http_response_code(403); exit('Invalid request token. Refresh and try again.'); } }
function setting(PDO $pdo,string $key,string $default=''): string { $s=$pdo->prepare('SELECT setting_value FROM site_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:(string)$v; }
function save_setting(PDO $pdo,string $key,string $value): void { $s=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$key,$value]); }
